:root {
  /* Tipografía */
  --wash-font-family: "Segoe UI", Arial, sans-serif;
  --wash-number-font: "IBM Plex Mono", Consolas, monospace;

  /* Textos */
  --wash-text-primary: #000000;
  --wash-text-secondary: #000000;

  /* Cuerda */
  --wash-fiber-color: #0A638F;

  /* Poleas */
  --wash-roller-fill: #D7D8DB;
  --wash-roller-border: #4E4E4E;
  --wash-roller-number: #000000;

  /* Cubas */
  --wash-tank-fill: #D7D8DB;
  --wash-tank-liquid: #A0CFE9;
  --wash-tank-border: #223151;

  /* Tuberías */
  --wash-steam-color: #930606;
  --wash-condensate-color: #4E4E4E;

  /* Control */
  --wash-control-color: #01524F;

  /* Válvulas */
  --wash-valve-color: #0E0E55;

  /* Agua desmineralizada */
  --wash-demin-line-color: #01524F;
  --wash-demin-valve-color: #0E0E55;
  --wash-demin-box-border: #223151;
  --wash-demin-text: #000000;

  /* Grosores */
  --wash-fiber-width: 2.8px;
  --wash-roller-border-width: 2.2px;
  --wash-process-width: 1.6px;
  --wash-process-main-width: 2px;
  --wash-control-width: 1.6px;
  --wash-tank-border-width: 1.4px;
  --wash-valve-width: 1.4px;
  --wash-demin-width: 1.6px;

  /* Numeración */
  --wash-roller-number-size: 13px;
}

/* ==========================================================
   ENTORNO TRANSPARENTE
   ========================================================== */

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.wash-widget {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  font-family: var(--wash-font-family);
  pointer-events: none;
}

.wash-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  shape-rendering: geometricPrecision;
}

/* Representación completamente estática */
.wash-widget,
.wash-widget * {
  animation: none !important;
  transition: none !important;
}

/* ==========================================================
   COLORES BASE DE LOS DEGRADADOS
   ========================================================== */

.roller-metal-base {
  stop-color: var(--wash-roller-fill);
}

.tank-metal-base {
  stop-color: var(--wash-tank-fill);
}

.tank-liquid-base {
  stop-color: var(--wash-tank-liquid);
}

/* ==========================================================
   CUBAS: METAL SATINADO
   ========================================================== */

.tank-group {
  filter: url("#wash3-tank-shadow");
}

.tank-upper {
  fill: url("#wash3-tank-metal");
  stroke: none;
}

.tank-lower {
  fill: url("#wash3-liquid-gradient");
  stroke: none;
  filter: url("#wash3-liquid-inset");
}

.tank-outline {
  fill: none;
  stroke: var(--wash-tank-border);
  stroke-width: var(--wash-tank-border-width);
  stroke-linejoin: round;
}

.tank-top-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 0.7px;
  stroke-linecap: round;
  opacity: 0.48;
}

.tank-bottom-shade {
  fill: none;
  stroke: #555D69;
  stroke-width: 0.65px;
  stroke-linecap: round;
  opacity: 0.14;
}

/* ==========================================================
   CUERDAS
   ========================================================== */

.fiber {
  fill: none;
  stroke: var(--wash-fiber-color);
  stroke-width: var(--wash-fiber-width);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

/* ==========================================================
   POLEAS: METAL SATINADO SIN ANILLO INTERIOR
   ========================================================== */

.roller-body {
  fill: url("#wash3-roller-metal");
  stroke: var(--wash-roller-border);
  stroke-width: var(--wash-roller-border-width);
  filter: url("#wash3-roller-shadow");
}

.roller-label {
  fill: var(--wash-roller-number);
  font-family: var(--wash-number-font);
  font-size: var(--wash-roller-number-size);
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

/* ==========================================================
   TUBERÍAS CONTINUAS
   ========================================================== */

.steam-line,
.condensate-line,
.control-line,
.demin-water-line {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

.steam-line {
  stroke: var(--wash-steam-color);
  stroke-width: var(--wash-process-width);
}

.condensate-line {
  stroke: var(--wash-condensate-color);
  stroke-width: var(--wash-process-width);
}

.steam-main,
.condensate-main {
  stroke-width: var(--wash-process-main-width);
}

/* Los extremos terminan en los bordes de las válvulas */
.valve-connection {
  stroke-linecap: butt;
}

/* ==========================================================
   CONTROL
   ========================================================== */

.control-line {
  stroke: var(--wash-control-color);
  stroke-width: var(--wash-control-width);
}

.control-node {
  fill: var(--wash-control-color);
  stroke: var(--wash-control-color);
  stroke-width: 1px;
}

/* ==========================================================
   VÁLVULAS TRANSPARENTES
   ========================================================== */

.valve-body,
.demin-valve-body {
  fill: none;
  stroke-width: var(--wash-valve-width);
  stroke-linecap: round;
  stroke-linejoin: round;
}

.valve-body {
  stroke: var(--wash-valve-color);
}

.valve-dot {
  fill: var(--wash-valve-color);
  stroke: var(--wash-valve-color);
  stroke-width: 1px;
}

/* Unión horizontal entre el centro de la válvula y su actuador */
.valve-link,
.demin-valve-link {
  fill: none;
  stroke-width: 0.7px;
  stroke-linecap: round;
}

.valve-link {
  stroke: var(--wash-valve-color);
}

.demin-valve-link {
  stroke: var(--wash-demin-valve-color);
}

/* ==========================================================
   AGUA DESMINERALIZADA
   ========================================================== */

.demin-water-line {
  stroke: var(--wash-demin-line-color);
  stroke-width: var(--wash-demin-width);
}

.demin-water-node {
  fill: var(--wash-demin-line-color);
  stroke: var(--wash-demin-line-color);
  stroke-width: 1px;
}

.demin-valve-body {
  stroke: var(--wash-demin-valve-color);
}

.demin-valve-dot {
  fill: var(--wash-demin-valve-color);
  stroke: var(--wash-demin-valve-color);
  stroke-width: 1px;
}

.demin-box-group {
  filter: url("#wash3-tank-shadow");
}

.demin-box {
  fill: url("#wash3-tank-metal");
  stroke: var(--wash-demin-box-border);
  stroke-width: var(--wash-tank-border-width);
  stroke-linejoin: round;
}

.demin-label {
  fill: var(--wash-demin-text);
  font-family: var(--wash-font-family);
  font-size: 15px;
  font-weight: 600;
  font-style: italic;
}

/* ==========================================================
   TEXTOS
   ========================================================== */

.labels text {
  font-family: var(--wash-font-family);
}

.text-steam {
  fill: var(--wash-steam-color);
  font-size: 12px;
  font-weight: 600;
}

.text-condensate {
  fill: var(--wash-condensate-color);
  font-size: 12px;
  font-weight: 600;
}

.text-footer {
  fill: var(--wash-text-secondary);
  font-size: 17px;
  font-style: italic;
  font-weight: 500;
}
